  function dashboardMetrics(){const m=getMetrics();const a=api.user?demo.overview:null;return a?{...m,revenue:a.revenue,cogs:a.purchaseCost,gross:a.grossProfit,expenses:a.expenses,net:a.netProfit,units:a.unitsSold,stock:a.inventoryValue,low:a.lowStock,products:a.products,completedOrders:a.completedOrders,today:a.salesToday,thisMonth:a.salesThisMonth,pending:a.pendingOrders}:m;}
  // Fill the dashboard cards, chart, bestsellers, and recent-order summaries.
  function renderOverview(){const m=dashboardMetrics();$("kpi-sales").textContent=rupees(m.revenue);$("kpi-gross").textContent=rupees(m.gross);$("kpi-net").textContent=rupees(m.net);$("kpi-net").classList.toggle("negative",m.net<0);$("gross-margin").textContent=`${m.revenue?((m.gross/m.revenue)*100).toFixed(1):"0.0"}% gross margin`;$("net-label").textContent=m.net<0?"OPERATING LOSS":"AFTER OPERATING EXPENSES";$("net-label").classList.toggle("negative",m.net<0);$("kpi-stock-value").textContent=rupees(m.stock);$("low-stock-caption").textContent=`${demo.products.reduce((n,p)=>n+Number(p.stock||0),0)} pieces across your collection`;$("low-stock-label").textContent=`${m.low} NEEDS ATTENTION`;$("pending-count").textContent=m.pending;$("business-breakdown").innerHTML=[[m.today,"Sales today",""],[m.thisMonth,"Sales this month",""],[m.cogs,"Cost of goods sold","negative"],[m.expenses,"Operating expenses","negative"],[m.gross,"Gross profit","positive"],[m.net,"Net profit / (loss)",m.net>=0?"positive":"negative"],[m.units,"Units sold Â· delivered",""],[m.products,"Active products",""],[m.low,"Low-stock products",""],[m.pending,"Open orders",""],[m.completedOrders,"Delivered orders",""]].map(([val,label,cls])=>`<div class="breakdown-row"><span>${label}</span><strong class="${cls}">${["Units sold Â· delivered","Active products","Low-stock products","Open orders","Delivered orders"].includes(label)?val:rupees(val)}</strong></div>`).join("")+`<div class="breakdown-caption">Gross profit = delivered revenue âˆ’ recorded product cost. Net profit = gross profit âˆ’ recorded operating expenses. Inventory purchases are not added again as expenses.</div>`;
    renderChart();const best=[...demo.products].sort((a,b)=>b.sold-a.sold).slice(0,4);$("bestseller-list").innerHTML=best.map((p,i)=>`<div class="bestseller-row"><img class="bestseller-thumb" src="${img(p.image,100)}" alt=""><div class="bestseller-info"><strong>${esc(p.name)}</strong><small>${p.sold} pieces in this sample collection</small></div><span>#0${i+1}</span></div>`).join("");$("recent-orders").innerHTML=demo.orders.slice(0,4).map(o=>`<div class="order-row"><div class="recent-info"><strong>${esc(o.id)} Â· ${esc(o.customer||o.customerName||"A customer")}</strong><small>${esc(o.products||"Order placed")} &nbsp;Â·&nbsp; ${esc(o.date||"Recently")}</small></div><span class="order-status">${esc(String(o.status).toUpperCase())}</span></div>`).join("")||'<div class="empty-rows">Your first order will find its way here.</div>';$("dashboard-date").textContent=new Intl.DateTimeFormat("en-IN",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date())+" Â· Your store, at a glance.";}
  function renderProductsPanel(){const rows=demo.products.map(p=>{const threshold=Number(p.minStock??5);const low=Number(p.stock)<=threshold;const margin=Number(p.price)>0?(Number(p.price)-Number(p.cost))/Number(p.price)*100:0;return`<tr class="${p.status==="Draft"?"archived-row":""}"><td><strong>${esc(p.name)}</strong><br><small>${esc(p.sku)}</small>${p.status==="Draft"?"<br><small>ARCHIVED</small>":""}</td><td>${esc(p.category)}</td><td>${rupees(p.cost)}</td><td>${rupees(p.price)}</td><td>${margin.toFixed(1)}%</td><td><span class="stock-pill ${low?"low":""}">${p.stock} ${low?"Â· LOW":"in stock"}</span></td><td>${rupees(p.stock*p.cost)}</td><td><div class="order-actions"><button class="table-action" data-edit-product="${esc(p.id)}">Edit</button>${p.status!=="Draft"?`<button class="table-action" data-archive="${esc(p.id)}">Archive</button>`:""}</div></td></tr>`;}).join("");$("dashboard-page").innerHTML=`<div class="dashboard-title-row"><div><span class="eyebrow"><span class="gold-rule"></span> THE THINGS YOU SELL</span><h1>Goods, <i>gathered.</i></h1><p>Carefully curated. Well looked after.</p></div><div class="period-select-wrap"><button class="button button-dark" id="new-product-button">Add a piece +</button></div></div><div class="demo-banner"><span>âœ³</span><div><strong>YOUR COLLECTION & ITS REAL COST</strong><p>Stock value uses units on hand Ã— purchase cost. Profit margins use actual selling price, excluding discounts.</p></div></div><div class="table-wrap"><table class="admin-data-table"><thead><tr><th>THE PIECE</th><th>COLLECTION</th><th>YOUR COST</th><th>SELLING</th><th>MARGIN</th><th>ON HAND</th><th>STOCK VALUE</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="8">No products yet.</td></tr>'}</tbody></table></div><div class="admin-action-row"><button class="table-action" id="export-products">Export products Â· CSV â†—</button></div>`;}
  function renderOrdersPanel(){const rows=demo.orders.map(o=>{const status=String(o.status).toUpperCase();const actions={PENDING:[["CONFIRMED","Confirm order"],["CANCELLED","Cancel"]],CONFIRMED:[["PROCESSING","Start processing"],["CANCELLED","Cancel"]],PROCESSING:[["SHIPPED","Mark shipped"],["CANCELLED","Cancel"]],SHIPPED:[["DELIVERED","Mark delivered"]],DELIVERED:[["REFUNDED","Record refund"]]};const available=actions[status]||[];if(api.user&&api.user.role==="staff"&&status==="DELIVERED")available.length=0;const controls=status==="DELIVERED"?`<label class="restock-label"><input type="checkbox" data-restock="${esc(o.id)}"> Restock return?</label>`:"";const buttons=available.map(([next,label])=>`<button class="table-action" data-fulfill="${esc(o.id)}" data-status="${next}">${label}</button>`).join("");const gross=status==="DELIVERED"?"Gross "+rupees(Number(o.amount??o.total??0)-Number(o.cost||0)):status==="REFUNDED"?"Refunded Â· "+rupees(o.amount??o.total??0):"â€”";return`<tr><td><strong>${esc(o.id)}</strong><br><small>${esc(o.date||"Recent")}</small></td><td>${esc(o.customer||o.customerName||"Customer")}<br><small>${esc(o.email||"")}</small></td><td>${esc(o.products||"Order items")}</td><td>${rupees(o.total??o.amount??0)}</td><td><span class="status-pill">${esc(status)}</span></td><td>${gross}</td><td><div class="order-actions">${controls}${buttons||"â€”"}</div></td></tr>`;}).join("");$("dashboard-page").innerHTML=`<div class="dashboard-title-row"><div><span class="eyebrow"><span class="gold-rule"></span> EVERY ORDER, THOUGHTFULLY HANDLED</span><h1>The order <i>book.</i></h1><p>Stock is reserved when you confirm an order. Only delivered orders count as sales.</p></div></div><div class="demo-banner"><span>âœ³</span><div><strong>STATUS CONTROLS WHEN STOCK MOVES</strong><p>Confirmed orders reserve stock; cancellations restore it. Mark deliveries explicitly. Refunded sales leave revenue and profit, and returned goods are restocked only when checked.</p></div></div><div class="table-wrap"><table class="admin-data-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>WHAT THEY FOUND</th><th>TOTAL</th><th>STATUS</th><th>ACTUAL GROSS</th><th>ACTION</th></tr></thead><tbody>${rows||'<tr><td colspan="7">No orders yet.</td></tr>'}</tbody></table></div><div class="admin-action-row"><button class="table-action" id="export-orders">Export orders Â· CSV â†—</button></div>`;}
  function renderExpensesPanel(){const rows=demo.expenses.map(e=>`<tr><td>${esc(e.date)}</td><td><span class="status-pill">${esc(e.category)}</span></td><td>${esc(e.description)}</td><td>${esc(e.reference||"â€”")}</td><td><strong>${rupees(e.amount)}</strong></td></tr>`).join("");const cats=[...new Set(demo.expenses.map(e=>e.category))];const sum=operatingExpenses();$("dashboard-page").innerHTML=`<div class="dashboard-title-row"><div><span class="eyebrow"><span class="gold-rule"></span> THE COST OF KEEPING THINGS GOING</span><h1>Money, <i>accounted for.</i></h1><p>Operating expenses only. Purchase costs are already recorded against products sold.</p></div><div><button class="button button-dark" id="new-expense-button">Record an expense +</button></div></div><div class="expense-summary"><div class="report-card"><span>TOTAL RECORDED SAMPLE EXPENSES</span><strong>${rupees(sum)}</strong></div>${cats.slice(0,2).map(c=>`<div class="report-card"><span>${esc(c.toUpperCase())} Â· SAMPLE</span><strong>${rupees(demo.expenses.filter(e=>e.category===c).reduce((n,e)=>n+e.amount,0))}</strong></div>`).join("")}</div><div class="table-wrap"><table class="admin-data-table"><thead><tr><th>DATE</th><th>TYPE</th><th>DESCRIPTION</th><th>REFERENCE</th><th>AMOUNT</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No expenses yet.</td></tr>'}</tbody></table></div><div class="demo-banner"><span>âœ³</span><div><strong>A CLEANER PROFIT & LOSS</strong><p>Net profit = sales âˆ’ cost of goods sold âˆ’ operating expenses. Inventory purchases are not booked again as operating expenses.</p></div></div>`;}
  // Present the selected reporting period and build downloadable business reports.
  function renderReportsPanel(){const m=dashboardMetrics();const reportRows=[["Delivered sales",m.revenue],["Cost of goods sold",m.cogs],["Gross profit",m.gross],["Operating expenses",m.expenses],["Net profit / (loss)",m.net],["Inventory value at purchase cost",m.stock]];$("dashboard-page").innerHTML=`<div class="dashboard-title-row"><div><span class="eyebrow"><span class="gold-rule"></span> THE NUMBERS, WITHOUT THE NOISE</span><h1>A better <i>read on it.</i></h1><p>Transparent, documented and counted only once.</p></div><div class="period-select-wrap"><span>THE PAST</span><select id="report-range"><option value="30">30 DAYS</option><option value="7">7 DAYS</option><option value="365">12 MONTHS</option></select></div></div><div class="demo-banner"><span>âœ³</span><div><strong>THE PROFIT & LOSS METHOD</strong><p>Only delivered orders count as revenue. Their recorded item costs are COGS, not new expenses. Operating costs are subtracted once. Unconfigured tax and gateway fees are never invented.</p></div><button id="export-report">Download CSV â†—</button></div><div class="reports-grid">${reportRows.map(([label,n])=>`<div class="report-card"><span>${esc(label.toUpperCase())}</span><strong class="${n<0?"negative":""}">${rupees(n)}</strong></div>`).join("")}</div><div class="analytics-card" style="margin-top:10px"><div class="card-heading"><div><span class="eyebrow">THE PROFIT & LOSS</span><h2>A simple, <i>honest account.</i></h2></div></div><div class="table-wrap"><table class="admin-data-table"><thead><tr><th>LINE ITEM</th><th>HOW IT'S COUNTED</th><th>INR</th></tr></thead><tbody>${reportRows.map(([label,n],i)=>`<tr><td>${esc(label)}</td><td>${["Delivered orders; discounts already reflected","Captured historical cost on delivered items","Delivered revenue minus product costs","Recorded operating expenses, once only","Gross profit minus operating expenses","Units currently in stock Ã— purchase price"][i]}</td><td><strong>${rupees(n)}</strong></td></tr>`).join("")}</tbody></table></div></div>`;const sel=$("report-range");if(sel)sel.value=String(state.range);}
  function renderAdmin(){if(!$("admin-view"))return;if(state.panel==="overview"){if(!$("kpi-sales"))$("dashboard-page").innerHTML=overviewTemplate;renderOverview();return;}if(state.panel==="products")renderProductsPanel();if(state.panel==="orders")renderOrdersPanel();if(state.panel==="expenses")renderExpensesPanel();if(state.panel==="reports")renderReportsPanel();}
  function showAdmin(panel="overview"){if(api.user&&api.user.role==="staff"){panel="orders";document.querySelectorAll(".dashboard-nav-item").forEach(b=>{b.hidden=b.dataset.panel!=="orders";});} $("store-view").classList.add("hidden");$("admin-view").classList.remove("hidden");$("admin-sidebar")?.classList.remove("admin-sidebar-open");state.panel=panel;document.querySelectorAll(".dashboard-nav-item").forEach(b=>b.classList.toggle("active",b.dataset.panel===panel));$("breadcrumb-current").textContent=panel.toUpperCase();if(api.user){$("connection-label").textContent="OWNER CONNECTED";$("connection-label").previousElementSibling.style.background="#85a27c";$("login-button").classList.add("hidden");$("logout-button").classList.remove("hidden");$("owner-name").textContent=api.user.email;$("owner-role").textContent=api.user.role.replace(/_/g," ");const title=$("demo-banner-title"),text=$("demo-banner-text"),action=$("demo-banner-action");if(title){title.textContent="YOUR LIVE BUSINESS RECORDS";text.textContent="Connected to your SR CLOTHING business database. Your live owner dashboard is separate from sample preview data.";action.textContent="Live owner account â†—";}}renderAdmin();window.scrollTo({top:0,behavior:"smooth"});}
