  // Quote CSV cells and neutralize spreadsheet formula prefixes before export.
  function downloadCsv(filename,headers,rows){const escapeCell=v=>{const value=String(v??"");const safe=/^[\s]*[=+\-@]/.test(value)?"'"+value:value;return`"${safe.replace(/"/g,'""')}"`};const content="\uFEFF"+[headers,...rows].map(row=>row.map(escapeCell).join(",")).join("\r\n");const url=URL.createObjectURL(new Blob([content],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportProducts(){downloadCsv("sr-clothing-products.csv",["SKU","Product","Category","Purchase cost INR","Selling price INR","Gross margin percent","Current stock","Inventory value INR"],demo.products.map(p=>[p.sku,p.name,p.category,p.cost,p.price,p.price?((p.price-p.cost)/p.price*100).toFixed(2):0,p.stock,p.stock*p.cost]));}
